package com.clinic.ui;
import com.clinic.model.*;
import com.clinic.service.ClinicManager;
import javax.swing.*; import javax.swing.border.EmptyBorder; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.time.format.DateTimeFormatter; import java.util.*;
public class AppointmentPanel extends JPanel {
 private final ClinicManager clinic; private final Runnable addAction; private final DefaultTableModel model=new DefaultTableModel(new String[]{"Appointment ID","Patient","Doctor","Date","Time","Reason","Status"},0){public boolean isCellEditable(int r,int c){return false;}}; private final JTable table=new JTable(model); private final JLabel count=new JLabel();
 public AppointmentPanel(ClinicManager c,Runnable add){clinic=c;addAction=add;setLayout(new BorderLayout(0,18));setBackground(Theme.CONTENT_BG);setBorder(new EmptyBorder(22,24,24,24));
 JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JPanel titles=new JPanel();titles.setOpaque(false);titles.setLayout(new BoxLayout(titles,BoxLayout.Y_AXIS));JLabel h=new JLabel("Appointments");h.setFont(Theme.font(Font.BOLD,25));h.setForeground(Theme.TEXT_DARK);JLabel sub=new JLabel("View and manage scheduled patient appointments");sub.setForeground(Theme.TEXT_MUTED);titles.add(h);titles.add(Box.createVerticalStrut(5));titles.add(sub);top.add(titles,BorderLayout.WEST);
 JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT));actions.setOpaque(false);JButton refresh=new JButton("Refresh");JButton addBtn=new JButton("+ Add Patient / Appointment");refresh.addActionListener(e->refresh());addBtn.addActionListener(e->addAction.run());actions.add(refresh);actions.add(addBtn);top.add(actions,BorderLayout.EAST);add(top,BorderLayout.NORTH);
 JPanel content=new JPanel(new BorderLayout(0,12));content.setBackground(Color.WHITE);content.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Theme.BORDER),new EmptyBorder(16,16,12,16)));JPanel th=new JPanel(new BorderLayout());th.setOpaque(false);JLabel label=new JLabel("Scheduled Appointments");label.setFont(Theme.font(Font.BOLD,17));th.add(label,BorderLayout.WEST);th.add(count,BorderLayout.EAST);content.add(th,BorderLayout.NORTH);
 table.setRowHeight(38);table.setFont(Theme.font(Font.PLAIN,13));table.setGridColor(Theme.BORDER);table.setShowVerticalLines(false);table.getTableHeader().setFont(Theme.font(Font.BOLD,13));table.getTableHeader().setBackground(new Color(0xE8ECEF));table.setFillsViewportHeight(true);content.add(new JScrollPane(table),BorderLayout.CENTER);add(content,BorderLayout.CENTER);refresh(); }
 public void refresh(){Map<String,String> ps=new HashMap<>(),ds=new HashMap<>();for(Patient p:clinic.getPatients())ps.put(p.getPatientId().toUpperCase(),p.getName());for(Doctor d:clinic.getDoctors())ds.put(d.getDoctorId().toUpperCase(),d.getName());model.setRowCount(0);for(Appointment a:clinic.getAppointments())model.addRow(new Object[]{a.getAppointmentId(),ps.getOrDefault(a.getPatientId().toUpperCase(),a.getPatientId()),a.getDoctorId().isEmpty()?"Unassigned":ds.getOrDefault(a.getDoctorId().toUpperCase(),a.getDoctorId()),a.getDateTime().format(DateTimeFormatter.ofPattern("MMM dd, yyyy")),a.getDateTime().format(DateTimeFormatter.ofPattern("h:mm a")),a.getReason(),a.getStatus().name()});count.setText(model.getRowCount()+" appointments");}
}
